<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {request} from './client'
import {sources,materialURL,object,requestIdentity} from './contracts'
import './release.css'
const props=defineProps({member:Object,rooms:Array})
const staff=computed(()=>['Teacher','Admin'].includes(props.member.role)),admin=computed(()=>props.member.role==='Admin')
const status=ref(null),room=ref(''),mode=ref('question'),task=ref('summary'),question=ref(''),document=ref(''),docs=ref([]),knowledge=ref([]),materials=ref([]),sessions=ref([]),sourceType=ref('IL Material'),sourceName=ref(''),conversations=ref([]),conversation=ref(null),result=ref(null),error=ref(''),note=ref(''),busy=ref(false),consent=ref(false),title=ref('Learning conversation'),tab=ref(props.member.role==='Admin'?'Insights':props.member.role==='Teacher'?'Study tools':'Assistant'),reason=ref(''),conversationPage=ref(0),messagePage=ref(0)
let pending=null
const flags=computed(()=>status.value?.features||{}),refs=computed(()=>sources(result.value)),allowance=computed(()=>status.value?.usage)
const tasks=computed(()=>[{id:'summary',flag:'ai.summaries',name:'Summary'},{id:'notes',flag:'ai.notes',name:'Study notes'},{id:'flashcards',flag:'ai.flashcards',name:'Flashcards'},{id:'questions',flag:'ai.questions',name:'Practice questions'},...(staff.value?[{id:'lesson_plan',flag:'ai.teacher',name:'Lesson plan'},{id:'revision',flag:'ai.teacher',name:'Revision material'},{id:'explanation',flag:'ai.teacher',name:'Explanation / examples'},{id:'quiz',flag:'ai.quiz',name:'Quiz draft'}]:[])])
const insight=computed(()=>result.value?.aggregates||result.value||{})
const selectedTask=computed(()=>tasks.value.find(t=>t.id===task.value))
const choices=computed(()=>sourceType.value==='IL Material'?materials.value:sessions.value)
async function run(fn){busy.value=true;error.value='';note.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function usage(){status.value=await request('ai','status',{},'GET')}
async function list(){if(flags.value['ai.assistant'])conversations.value=await request('ai','conversations',{page:conversationPage.value})}
async function loadSources(){docs.value=[];knowledge.value=[];materials.value=[];sessions.value=[];document.value='';sourceName.value='';if(!room.value)return;docs.value=await request('release','learning_sources',{classroom:room.value});if(staff.value){const d=await request('api','classroom_detail',{name:room.value});materials.value=d.materials||[];sessions.value=d.sessions||[];if(flags.value['ai.rag'])knowledge.value=await request('knowledge','documents',{classroom:room.value})}}
async function changeRoom(){result.value=null;conversation.value=null;pending=null;await run(loadSources)}
async function open(c){await run(async()=>{room.value=c.classroom;result.value=null;pending=null;await loadSources();messagePage.value=0;conversation.value=await request('ai','conversation',{name:c.name,page:0});tab.value='Assistant'})}
async function messages(){conversation.value=await request('ai','conversation',{name:conversation.value.name,page:messagePage.value})}
async function create(){await run(async()=>{const c=await request('ai','create_conversation',{classroom:room.value,title:title.value});conversation.value={...c,title:title.value,status:'Active',messages:[]};await list()})}
async function archive(remove=false){await run(async()=>{const r=await request('ai','archive_conversation',{name:conversation.value.name,delete:remove});conversation.value=null;await list();note.value=remove?'Deletion scheduled after '+r.purge_after:'Conversation archived.'})}
async function send(module,method,args){pending=requestIdentity(pending,{module,method,args});result.value=await request(module,method,{...args,request_id:pending.id});pending=null;await usage()}
async function ask(){await run(async()=>{await send('ai','course_question',{classroom:room.value,question:question.value,conversation:conversation.value?.name||null,consent:consent.value,mode:mode.value});if(conversation.value)await messages()})}
async function generate(){await run(async()=>{const args={classroom:room.value,document:document.value||null,instruction:question.value};if(['lesson_plan','revision','explanation','quiz'].includes(task.value))await send('ai','teacher_assistant',{...args,task:task.value});else await send('ai',task.value,args)})}
async function index(){await run(async()=>{await request('knowledge','ingest',{classroom:room.value,source_type:sourceType.value,source_name:sourceName.value});await loadSources();note.value='Indexing requested. Refresh to see the worker result.'})}
async function deactivate(d){await run(async()=>{await request('knowledge','deactivate',{document:d.name});await loadSources()})}
function storedSources(m){const s=object(m.citations);return sources({sources:Array.isArray(s)?s:[]})}
onMounted(()=>run(async()=>{await usage();await list()}))
</script>
<template><section class="release"><h1>Premium AI learning studio</h1><p>Grounded in your authorized course materials. Generated teaching and assessment content remains a draft.</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="note" role="status">{{note}}</p><p v-if="busy" role="status" aria-live="polite">Working — provider requests may take a moment. Do not submit another request.</p><button class="button subtle" :disabled="busy" @click="run(async()=>{await usage();await list();await loadSources()})">Refresh</button>
<p v-if="status&&!status.available" class="status">AI is unavailable for this account or provider configuration. Enabled features and backend checks determine access.</p><p v-if="allowance">Your credits: {{allowance.user_credits}} · Organization: {{allowance.tenant_used}} / {{allowance.tenant_limit}} · {{allowance.tenant_remaining}} remaining · {{allowance.period}}. {{allowance.reset}}</p><p v-if="allowance?.mode==='Individual'">{{allowance.allocated}} allocated · {{allowance.personal_remaining}} personal credits remaining</p><p v-if="allowance?.mode==='Shared'">Shared Institute Pool — individual caps are paused.</p><p v-if="(allowance?.effective_remaining??allowance?.tenant_remaining)===0" role="status">Your AI allowance is exhausted. Contact your administrator.</p>
<label>Authorized classroom<select v-model="room" :disabled="busy" @change="changeRoom"><option value="">Choose a classroom</option><option v-for="r in rooms" :key="r.name" :value="r.name">{{r.title}} {{r.access?.allowed===false?'— '+r.access.reason:''}}</option></select></label>
<nav aria-label="AI tools"><button v-for="t in admin?['Insights']:member.role==='Teacher'?['Study tools','Knowledge']:['Assistant','Study tools','Search','Recommendations']" :key="t" class="button subtle" :aria-pressed="tab===t" @click="tab=t;result=null">{{t}}</button></nav>
<template v-if="tab==='Assistant'"><div class="grid"><article class="panel"><h2>My private conversations</h2><p v-if="!flags['ai.assistant']">Learning assistant is not included in your resolved plan.</p><button v-for="c in conversations" :key="c.name" class="button subtle" :disabled="busy" @click="open(c)">{{c.title}} · {{c.status}}</button><p v-if="!conversations.length">No accessible conversations on this page.</p><button class="button subtle" :disabled="busy||!conversationPage" @click="conversationPage--;run(list)">Previous</button><button class="button subtle" :disabled="busy||conversations.length<30" @click="conversationPage++;run(list)">Next</button><label>Conversation title<input v-model="title" maxlength="120"></label><button class="button primary" :disabled="busy||!room||!flags['ai.assistant']" @click="create">New conversation</button></article><article class="panel"><h2>{{conversation?.title||'Course question'}}</h2><template v-if="conversation"><button class="button subtle" :disabled="busy" @click="archive()">Archive</button><button class="button subtle" :disabled="busy" @click="archive(true)">Schedule deletion</button><article v-for="(m,i) in conversation.messages" :key="i" class="message"><strong>{{m.role}}</strong><p class="answer">{{m.content}}</p><ul class="sources"><li v-for="s in storedSources(m)" :key="s.id">{{s.title}} · {{s.section}} · {{s.classroom}} <a v-if="materialURL(s)" :href="materialURL(s)" target="_blank" rel="noopener">Open material</a></li></ul></article><button class="button subtle" :disabled="busy||!messagePage" @click="messagePage--;run(messages)">Earlier messages</button><button class="button subtle" :disabled="busy||conversation.messages.length<50" @click="messagePage++;run(messages)">Later messages</button></template><form @submit.prevent="ask"><label>Mode<select v-model="mode"><option v-for="m in ['question','explain','simplify','examples']">{{m}}</option></select></label><label>Question<textarea v-model="question" maxlength="2000" required></textarea></label><label class="check"><input v-model="consent" type="checkbox">I agree to send this question and authorized course context to the configured AI provider. Do not include private contact details or secrets.</label><button class="button primary" :disabled="busy||!room||!consent||!flags['ai.assistant']||!flags['ai.rag']||conversation?.status==='Archived'">Ask with course sources</button></form></article></div></template>
<form v-else-if="tab==='Study tools'" class="panel" @submit.prevent="generate"><label>Tool<select v-model="task"><option v-for="t in tasks" :key="t.id" :value="t.id" :disabled="!flags[t.flag]">{{t.name}} {{flags[t.flag]?'':'— not entitled'}}</option></select></label><label>Indexed source<select v-model="document"><option value="">All ready sources (bounded context)</option><option v-for="d in docs" :key="d.name" :value="d.name">{{d.title}} · v{{d.version}}</option></select></label><p v-if="!docs.length">No ready sources. Ask an authorized teacher to index supported material.</p><label>Instructions<textarea v-model="question" maxlength="2000" placeholder="Level, language or focus"></textarea></label><button class="button primary" :disabled="busy||!room||!docs.length||!flags[selectedTask?.flag]">Generate private draft</button><p>Use Papers to create and explicitly review/publish an official quiz. Generated feedback never changes grades automatically.</p></form>
<form v-else-if="tab==='Search'" class="panel" @submit.prevent="run(()=>send('ai','search',{classroom:room,query:question}))"><label>Search authorized material<input v-model="question" maxlength="2000" required></label><button class="button primary" :disabled="busy||!room||!flags['ai.search']">Semantic search</button></form>
<article v-else-if="tab==='Recommendations'" class="panel"><p>Practice suggestions use your actual graded assessment evidence. Insufficient evidence is reported explicitly.</p><button class="button primary" :disabled="busy||!room||!flags['ai.recommendations']" @click="run(async()=>result=await request('ai','recommendations',{classroom:room}))">Find practice priorities</button></article>
<article v-else-if="tab==='Insights'" class="panel"><p>Tenant-local aggregates only. Small cohorts are suppressed; private conversations are never included.</p><button class="button primary" :disabled="busy||!room||!flags['ai.analytics']" @click="run(async()=>result=await request('ai','admin_insights',{classroom:room,explain:false}))">Load verified aggregates</button><button class="button subtle" :disabled="busy||!room||!flags['ai.analytics']" @click="run(()=>send('ai','admin_insights',{classroom:room,explain:true}))">Explain aggregates with AI</button><button class="button subtle" :disabled="busy||!flags['ai.analytics']" @click="run(async()=>result=await request('ai','usage',{tenant:true}))">Organization AI usage</button></article>
<template v-else-if="tab==='Knowledge'"><form class="panel" @submit.prevent="index"><h2>Course knowledge</h2><p>PDF text, DOCX, PPTX, TXT and lesson/session text. Legacy DOC/PPT need conversion; scanned PDFs may need a text version. Indexing consumes configured AI credits.</p><label>Source type<select v-model="sourceType" @change="sourceName='' "><option>IL Material</option><option>IL Session</option><option>Course Lesson</option></select></label><label v-if="sourceType!=='Course Lesson'">Existing source<select v-model="sourceName" required><option value="">Choose material/session</option><option v-for="s in choices" :key="s.name" :value="s.name">{{s.title}}</option></select></label><label v-else>Existing native lesson ID<input v-model="sourceName" required><small>The backend verifies its course mapping and your permissions.</small></label><button class="button primary" :disabled="busy||!room||!flags['ai.rag']">Index / reindex selected source</button></form><article v-for="d in knowledge" :key="d.name" class="panel"><strong>{{d.title}}</strong><p>{{d.status}} · v{{d.version}} · {{d.error_code||'No reported error'}}</p><button class="button subtle" :disabled="busy" @click="deactivate(d)">Deactivate knowledge</button></article><p v-if="!knowledge.length">No knowledge records for this classroom.</p><details><summary>Reset an expired/broken course index</summary><label>Review reason<input v-model="reason" required></label><p>Reset removes retrieval access until material is reindexed.</p><button class="button subtle" :disabled="busy||!room||!reason" @click="run(async()=>{if(!window.confirm('Disable this course index? Reindexing is required afterwards.'))return;await request('knowledge','reset_index',{classroom:room,reason});await loadSources()})">Confirm index reset</button></details></template>
<article v-if="result" class="panel" aria-live="polite"><h2>{{result.draft?'Draft result':'Result'}}</h2><p v-if="result.supported===false" class="status">Insufficient course evidence.</p><p v-if="result.answer||result.explanation" class="answer">{{result.answer||result.explanation}}</p><details v-for="(c,i) in result.cards||[]" :key="i"><summary>{{c.front}}</summary><p>{{c.back}}</p><small>Source {{c.source}}</small></details><article v-for="(q,i) in result.questions||[]" :key="i" class="message"><strong>{{i+1}}. {{q.prompt}}</strong><ol><li v-for="o in q.options">{{o}}</li></ol><details><summary>Practice answer</summary>{{q.answer===null?'Teacher-reviewed written response':q.options[q.answer]}}</details><small>Source {{q.source}}</small></article><article v-for="(r,i) in result.results||[]" :key="i"><h3>{{r.title}}</h3><p>{{r.excerpt}}</p><small>{{r.section}} · relevance {{r.score}}</small><a v-if="materialURL(r)" :href="materialURL(r)" target="_blank" rel="noopener">Open source</a></article><ul v-if="refs.length" class="sources"><li v-for="s in refs" :key="s.id">{{s.id}} · {{s.title}} · {{s.section}} · {{s.classroom}} <a v-if="materialURL(s)" :href="materialURL(s)" target="_blank" rel="noopener">Open material</a></li></ul><template v-if="tab==='Recommendations'"><p>{{result.message}}</p><p class="muted">{{result.basis}}</p><article v-for="(e,i) in result.evidence||[]" :key="i" class="message"><h3>{{e.topic}}</h3><p>{{e.reason}} · Paper {{e.paper}}, question {{e.question}}</p><p>{{e.recommendation}}</p><ul><li v-for="m in e.suggested_materials||[]" :key="m.name"><a :href="materialURL({source_type:'IL Material',material:m.name})" target="_blank" rel="noopener">{{m.title}}</a></li></ul><small>{{e.matching_basis}}</small></article></template><template v-if="tab==='Insights'"><p v-if="insight.sufficient_data===false" class="status">{{insight.reason}}</p><div v-if="insight.sufficient_data" class="grid"><p>Assessed students: {{insight.assessed_students}}</p><p>Graded attempts: {{insight.graded_attempts}}</p><p>Weighted score: {{insight.weighted_score_percent===null?'Unavailable':insight.weighted_score_percent+'%'}}</p></div><p v-for="(a,i) in insight.attendance||[]" :key="i">Attendance {{a.status}}: {{a.count}}</p><article v-for="(p,i) in insight.practice_priorities||[]" :key="i" class="message">{{p.question_topic}} · {{p.students_with_incorrect_answer}} students with documented incorrect answers</article><p class="muted">{{insight.topic_sample}} {{insight.scope}}</p><p v-if="result.allowance">{{result.allowance.period}} · {{result.allowance.tenant_used}} credits used · {{result.allowance.tenant_remaining}} remaining</p><div v-if="result.requests||insight.ai_usage" class="scroll"><table><thead><tr><th>Feature</th><th>Credits</th><th>Tokens</th><th>State / requests</th></tr></thead><tbody><tr v-for="(u,i) in (result.requests||insight.ai_usage||[]).slice(0,50)" :key="i"><td>{{u.feature}}</td><td>{{u.charged_units??u.credits}}</td><td>{{u.total_tokens??u.tokens}}</td><td>{{u.state||u.requests}}</td></tr></tbody></table><p class="muted">Showing up to 50 rows from the bounded server response. No conversation content.</p></div></template></article></section></template>
